# apply: each anchor must match exactly one line
missing=[]
for i,(anchor,newline) in enumerate(EDITS):
    hits=[j for j,l in enumerate(lines) if anchor in l]
    if len(hits)!=1:
        missing.append((anchor,len(hits)))
    else:
        lines[hits[0]]=newline
if missing:
    print("ANCHOR PROBLEMS (not applied):"); 
    for a,c in missing: print(f"  count={c} :: {a[:60]}")
    raise SystemExit(1)

out='\n'.join(lines)
tmp=DST+'.tmp'
with open(tmp,'w',encoding='utf-8') as fh:
    fh.write(out); fh.flush(); os.fsync(fh.fileno())
os.replace(tmp,DST)
print(f"WROTE {DST} ({len(lines)} lines, {out.count(chr(10))+1} newlines)")
# guard checks: forbidden phrasings must be gone
for bad in ["worse than chance","hypermitonic","All four would survive peer review",
            "867 external rows","excluded zero in Hong Kong and (just)","is unmeasured",
            "single level-A estimate reported at record level"]:
    print(f"  [{'GONE' if bad not in out else 'STILL PRESENT!!'}] {bad!r}")
